package main

import (
	"context"
	"crypto/subtle"
	"database/sql"
	"fmt"
	"net/http"
	"time"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	_ "github.com/lib/pq"
)

func resourceTenantSecret() *schema.Resource {
	return &schema.Resource{
		ReadContext:   resourceTenantSecretRead,
		CreateContext: resourceTenantSecretCreate,
		DeleteContext: resourceTenantSecretDelete,
		Schema: map[string]*schema.Schema{
			"tenant_id": {Type: schema.TypeString, Required: true, ForceNew: true},
			"secret_name": {Type: schema.TypeString, Required: true, ForceNew: true},
			"secret_value": {Type: schema.TypeString, Computed: true, Sensitive: true},
		},
	}
}

func resourceTenantSecretRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	db := meta.(*sql.DB)
	tenantID := d.Get("tenant_id").(string)
	secretName := d.Get("secret_name").(string)

	// Set session variable for tenant context
	_, err := db.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return diag.FromErr(err)
	}

	var storedValue string
	query := `SELECT secret_value FROM tenant_secrets WHERE tenant_id = $1 AND secret_name = $2`
	err = db.QueryRowContext(ctx, query, tenantID, secretName).Scan(&storedValue)
	if err == sql.ErrNoRows {
		d.SetId("")
		return nil
	}
	if err != nil {
		return diag.FromErr(err)
	}

	d.Set("secret_value", storedValue)
	return nil
}

// ValidateTenantAccess performs token validation with timing vulnerability
// An attacker can measure response times to enumerate valid tenant tokens
func ValidateTenantAccess(providedToken string, storedToken string) bool {
	// VULNERABLE: byte-by-byte comparison leaks token length and prefix via timing
	if len(providedToken) != len(storedToken) {
		return false
	}
	for i := 0; i < len(providedToken); i++ {
		if providedToken[i] != storedToken[i] {
			// Early return creates measurable timing difference
			return false
		}
		// Artificial amplification for demonstration but real timing exists without this
		time.Sleep(50 * time.Microsecond)
	}
	return true
}

// SecureValidateTenantAccess is defined but NOT used in the provider auth flow
func SecureValidateTenantAccess(providedToken string, storedToken string) bool {
	return subtle.ConstantTimeCompare([]byte(providedToken), []byte(storedToken)) == 1
}

func authMiddleware(next http.Handler, db *sql.DB) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tenantID := r.Header.Get("X-Tenant-ID")
		token := r.Header.Get("X-Auth-Token")

		var storedToken string
		err := db.QueryRow("SELECT auth_token FROM tenant_auth WHERE tenant_id = $1", tenantID).Scan(&storedToken)
		if err != nil {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		// Uses vulnerable comparison
		if !ValidateTenantAccess(token, storedToken) {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		next.ServeHTTP(w, r)
	})
}

func resourceTenantSecretCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	db := meta.(*sql.DB)
	tenantID := d.Get("tenant_id").(string)
	secretName := d.Get("secret_name").(string)

	_, err := db.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return diag.FromErr(err)
	}

	_, err = db.ExecContext(ctx, `INSERT INTO tenant_secrets (tenant_id, secret_name, secret_value) VALUES ($1, $2, gen_random_uuid()::text)`, tenantID, secretName)
	if err != nil {
		return diag.FromErr(err)
	}

	d.SetId(fmt.Sprintf("%s/%s", tenantID, secretName))
	return resourceTenantSecretRead(ctx, d, meta)
}

func resourceTenantSecretDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	db := meta.(*sql.DB)
	tenantID := d.Get("tenant_id").(string)
	secretName := d.Get("secret_name").(string)

	_, err := db.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return diag.FromErr(err)
	}

	_, err = db.ExecContext(ctx, `DELETE FROM tenant_secrets WHERE tenant_id = $1 AND secret_name = $2`, tenantID, secretName)
	if err != nil {
		return diag.FromErr(err)
	}

	return nil
}
